#!/usr/bin/env python3
"""Patch the Android project generated by `flutter create` for ONE ORT (the dashboard app).
Usage: python3 tool/patch_ort.py ort
"""
import pathlib, re, shutil, sys

root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "ort")
android = root / "android"
app = android / "app"
tool = pathlib.Path(__file__).parent

# ── Manifest ──
manifest = app / "src/main/AndroidManifest.xml"
m = manifest.read_text()
perms = ["INTERNET", "ACCESS_NETWORK_STATE", "CAMERA", "RECORD_AUDIO", "MODIFY_AUDIO_SETTINGS",
         "ACCESS_FINE_LOCATION", "ACCESS_COARSE_LOCATION", "POST_NOTIFICATIONS", "VIBRATE", "USE_BIOMETRIC", "NFC"]
block = "\n".join(f'    <uses-permission android:name="android.permission.{p}"/>' for p in perms if f'permission.{p}"' not in m)
m = m.replace("<application", block + '\n    <uses-feature android:name="android.hardware.nfc" android:required="false"/>\n    <application', 1)
m = re.sub(r'android:label="[^"]*"', 'android:label="ONE ORT"', m, count=1)
manifest.write_text(m)

# ── MainActivity: FragmentActivity for the biometric prompt ──
for old in (app / "src/main").rglob("MainActivity.*"):
    pkg = re.search(r"package\s+([\w.]+)", old.read_text()).group(1)
    old.write_text(f"package {pkg}\n\nimport io.flutter.embedding.android.FlutterFragmentActivity\n\nclass MainActivity : FlutterFragmentActivity()\n")

# ── Build file: minSdk 24, Java 17, desugaring (notifications), AppCompat ──
kts = (app / "build.gradle.kts").exists()
bf = app / ("build.gradle.kts" if kts else "build.gradle")
g = bf.read_text()
g = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 24", g)
g = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 24", g)
g = g.replace("JavaVersion.VERSION_1_8", "JavaVersion.VERSION_17")
g = re.sub(r"ndkVersion\s*=\s*flutter\.ndkVersion", 'ndkVersion = "27.0.12077973"', g)
# No code / resource shrinking: it strips the notification icon (looked up by name) and plugin classes,
# which crashes the app at start.
if kts:
    g = g.replace('signingConfig = signingConfigs.getByName("debug")',
                  'signingConfig = signingConfigs.getByName("debug")\n            isMinifyEnabled = false\n            isShrinkResources = false')
else:
    g = g.replace("signingConfig = signingConfigs.debug",
                  "signingConfig = signingConfigs.debug\n            minifyEnabled false\n            shrinkResources false")
if kts:
    g = re.sub(r"compileOptions\s*\{", "compileOptions {\n        isCoreLibraryDesugaringEnabled = true", g, count=1)
    g += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n    implementation("androidx.appcompat:appcompat:1.7.0")\n}\n'
else:
    g = re.sub(r"compileOptions\s*\{", "compileOptions {\n        coreLibraryDesugaringEnabled true", g, count=1)
    g += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n    implementation 'androidx.appcompat:appcompat:1.7.0'\n}\n"
bf.write_text(g)

for sty in (app / "src/main/res").glob("values*/styles.xml"):
    t = sty.read_text()
    t = re.sub(r'parent="@android:style/Theme\.[^"]*"', 'parent="Theme.AppCompat.DayNight.NoActionBar"', t)
    sty.write_text(t)

# ── Toolchain (same as the ONE app) ──
for name in ("settings.gradle", "settings.gradle.kts"):
    p = android / name
    if p.exists():
        s = p.read_text()
        s = re.sub(r'(id\s*\(?\s*"com\.android\.application"\s*\)?\s*version\s*)"[^"]+"', r'\g<1>"8.7.3"', s)
        s = re.sub(r'(id\s*\(?\s*"org\.jetbrains\.kotlin\.android"\s*\)?\s*version\s*)"[^"]+"', r'\g<1>"2.1.0"', s)
        p.write_text(s)
wp = android / "gradle/wrapper/gradle-wrapper.properties"
wp.write_text(re.sub(r"gradle-[\d.]+-(all|bin)\.zip", "gradle-8.12-all.zip", wp.read_text()))

# ── Brand icons (launcher + notification) ──
res_src = tool / "res"
for f in res_src.rglob("*"):
    if f.is_file():
        out = app / "src/main/res" / f.relative_to(res_src)
        out.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy(f, out)
assert "inifyEnabled" in g, "release block not found"
print("ONE ORT patched")
